// cfgxAs converts a value returned by a Getter to T. A []any list is
// converted element by element.
func cfgxAs[T any](key string, raw any) (T, error) {
	if val, ok := raw.(T); ok {
		return val, nil
	}
	var zero T
	if items, ok := raw.([]any); ok {
		switch out := any(&zero).(type) {
		case *[]string:
			if *out, ok = cfgxElems[string](items); ok {
				return zero, nil
			}
		case *[]int:
			if *out, ok = cfgxElems[int](items); ok {
				return zero, nil
			}
		}
	}
	return zero, fmt.Errorf("%s: getter returned %T, want %T", key, raw, zero)
}

// cfgxElems asserts every item to E.
func cfgxElems[E any](items []any) ([]E, bool) {
	out := make([]E, len(items))
	for i, item := range items {
		e, ok := item.(E)
		if !ok {
			return nil, false
		}
		out[i] = e
	}
	return out, true
}

